export function isGraded(e){return null!=e&&""!==e&&!isNaN(Number(e))}export function gradeBookLetter(e,r,t){if(!isGraded(e)||!t||!t.length)return"";const n=Number(r);return n?t[gradeBookLetterIndex(e,n,t)].letter:""}export function gradeBookLetterIndex(e,r,t){const n=Number(e)/Number(r)*100;if(n>=Number(t[0].highRange))return 0;for(let e=0;e<t.length;e++)if(n>=Number(t[e].lowRange))return e;return t.length-1}export function studentDisplayName(e){return e?e.name?e.name:[e.student,e.surname].filter(e=>!!e).join(" "):""}export const GradeBookTagColors=["blue","light-blue","amber","teal","red","light-green","purple","blue-grey"];export function gradeBookSeriesIndex(e){const r=parseInt(e,10);return isNaN(r)||r<0?0:r%GradeBookTagColors.length}